/** Send an authenticated API request without opening a public network listener. */
async function request(method: 'GET' | 'POST' | 'PUT' | 'PATCH', url: string, payload?: unknown, session = token) {
  return app.inject({ method, url, headers: {
    'x-installation-id': device.requestId, 'x-installation-secret': device.secret,
    ...(session ? { authorization: `Bearer ${session}` } : {}),
  }, payload });
}

/** Require successful JSON responses so setup failures cannot masquerade as passing assertions. */
async function ok<T>(method: 'GET' | 'POST' | 'PUT' | 'PATCH', url: string, payload?: unknown, session = token): Promise<T> {
  const result = await request(method, url, payload, session);
  assert.equal(result.statusCode, 200, result.body);
  return result.json<T>();
}

