test('gateway failures are visible and back off; responses require explicit acceptance', async () => {
  await ok('PUT', `/customers/${customer.id}`, { name: customer.name, phone: customer.phone, address: customer.address, whatsappConsent: true });
  const upcoming = await ok<Job>('POST', '/jobs', {
    bikeId: vehicle.id, complaint: 'Retry service', odometer: 2200, serviceDate: '2026-11-03', nextServiceDate: '2026-11-05', laborPaise: 0, gstBasisPoints: 0, parts: [],
  });
  await ok('PATCH', `/jobs/${upcoming.id}`, { status: 'completed' });
  const reminders = await ok<Page<Reminder>>('GET', `/reminders?search=${upcoming.id}`);
  const now = new Date('2026-11-03T08:00:00Z');
  await transaction(pool, async db => save(db, 'reminders', { ...reminders.items[0], nextAttempt: now.toISOString() }));
  const result = await runReminders(pool, async () => { throw new Error('Provider secret response'); }, now);
  assert.equal(result.failed, 1);
  const failed = await get(pool, 'reminders', reminders.items[0].id);
  assert.equal(failed?.status, 'failed'); assert.equal(failed?.attempts, 1);
  assert.ok(failed!.nextAttempt > now.toISOString());
  assert.equal(failed?.error?.includes('secret'), false);
  let retried = 0;
  await runReminders(pool, async () => { retried++; }, now);
  assert.equal(retried, 0);
  process.env.WHATSAPP_URL = 'http://insecure.example.test';
  process.env.WHATSAPP_TOKEN = 'test-only';
  await assert.rejects(() => sendWhatsApp({ to: customer.phone, template: 'test', variables: { customerName: 'Test', garageName: 'Test', registration: 'TEST', serviceDate: today }, idempotencyKey: randomUUID() }), /HTTPS/);
  delete process.env.WHATSAPP_URL; delete process.env.WHATSAPP_TOKEN; delete process.env.REMINDERS_ENABLED;
});

