test('WhatsApp status queue is consent-gated, idempotent and sends the exact latest work note', async () => {
  const input = { bikeId: vehicle.id, complaint: 'Tracking messages test', odometer: 2200, serviceDate: '2026-11-04', laborPaise: 0, gstBasisPoints: 0, parts: [] };
  const service = await ok<Job>('POST', '/jobs', input);
  const tracked = await ok<Job>('POST', `/jobs/${service.id}/tracking`, { stage: 'waiting_parts', note: 'Replacement brake pads ordered', promisedDelivery: '2026-11-05T18:00:00+05:30' });
  const eventId = tracked.timeline![tracked.timeline!.length - 1].id;
  assert.equal((await request('POST', `/jobs/${service.id}/share-status`, { eventId })).statusCode, 409, 'Unconfigured gateway must be reported');
  process.env.REMINDERS_ENABLED = 'true'; process.env.WHATSAPP_URL = 'https://gateway.example.test/send'; process.env.WHATSAPP_TOKEN = 'fixture-only';
  try {
    const queued = await ok<Reminder>('POST', `/jobs/${service.id}/share-status`, { eventId });
    assert.equal(queued.purpose, 'service_status');
    assert.equal((await ok<Reminder>('POST', `/jobs/${service.id}/share-status`, { eventId })).id, queued.id);
    await runReminders(pool, async payload => {
      if (payload.idempotencyKey === queued.id) {
        assert.equal(payload.template, 'bike_service_status');
        assert.equal(payload.variables.serviceStatus, 'waiting parts');
        assert.equal(payload.variables.workNote, 'Replacement brake pads ordered');
        assert.equal(payload.variables.promisedDelivery, '2026-11-05T18:00:00+05:30');
      }
    }, new Date(Date.now() + 1000));
    assert.equal((await get(pool, 'reminders', queued.id))?.status, 'sent');
    await ok('PUT', `/customers/${customer.id}`, { name: customer.name, phone: customer.phone, address: customer.address, whatsappConsent: false });
    assert.equal((await request('POST', `/jobs/${service.id}/share-status`, { eventId })).statusCode, 409);
    await ok('PUT', `/customers/${customer.id}`, { name: customer.name, phone: customer.phone, address: customer.address, whatsappConsent: true });
    const newer = await ok<Job>('POST', `/jobs/${service.id}/tracking`, { stage: 'working', note: 'Brake pads arrived, fitting started' });
    const newerId = newer.timeline![newer.timeline!.length - 1].id;
    await ok('POST', `/jobs/${service.id}/share-status`, { eventId: newerId });
    await ok('POST', `/jobs/${service.id}/tracking`, { stage: 'quality_check', note: 'Road safety inspection underway' });
    await runReminders(pool, async payload => {
      assert.notEqual(payload.idempotencyKey, newerId, 'Superseded work status must not be sent');
    }, new Date(Date.now() + 2000));
    assert.equal((await get(pool, 'reminders', newerId))?.status, 'skipped');
    await ok('PATCH', `/jobs/${service.id}`, { status: 'completed' });
    const delivered = await ok<Job>('POST', `/jobs/${service.id}/tracking`, { stage: 'delivered', note: 'Bike collected by customer' });
    assert.equal(delivered.stage, 'delivered');
    assert.equal((await request('POST', `/jobs/${service.id}/tracking`, { stage: 'ready', note: 'Cannot reopen tracking' })).statusCode, 409);
  } finally {
    delete process.env.REMINDERS_ENABLED; delete process.env.WHATSAPP_URL; delete process.env.WHATSAPP_TOKEN;
  }
});

