test('business backup restores into an empty garage with accounting and stock integrity', async () => {
  const backup = await exportBackup(pool);
  const memory = newDb();
  const restorePool: Pool = new (memory.adapters.createPg().Pool)();
  try {
    await migrate(restorePool);
    const restoreOwner = await createUser(restorePool, { name: 'Restore Owner', email: 'restore@example.test', password: 'Restore-test-password!', role: 'owner' });
    const result = await restoreBackup(restorePool, backup, restoreOwner.id);
    assert.ok(result.restored > 0);
    assert.equal((await get(restorePool, 'items', stock.id))!.quantity, 10);
    assert.equal((await get(restorePool, 'invoices', invoice.id))!.totalPaise, 75000);
    await assert.rejects(() => restoreBackup(restorePool, backup, restoreOwner.id), /empty garage/);
    const corrupt = structuredClone(backup);
    corrupt.records.items[0].quantity += 1;
    await assert.rejects(() => restoreBackup(restorePool, corrupt, restoreOwner.id), /stock movement/);
  } finally { await restorePool.end(); }
});

test('PostgreSQL transaction rollback and concurrent completion', { skip: !liveDatabase }, async () => {
  const before = (await get(pool, 'items', stock.id))!.quantity;
  await assert.rejects(() => transaction(pool, async db => {
    await save(db, 'items', { ...stock, quantity: 1 });
    throw new Error('Rollback test');
  }), /Rollback test/);
  assert.equal((await get(pool, 'items', stock.id))!.quantity, before);
  const concurrent = await ok<Job>('POST', '/jobs', {
    bikeId: vehicle.id, complaint: 'Concurrent completion test', odometer: 2300, serviceDate: '2026-11-04', laborPaise: 0, gstBasisPoints: 0, parts: [{ itemId: stock.id, quantity: 1 }],
  });
  const responses = await Promise.all([
    request('PATCH', `/jobs/${concurrent.id}`, { status: 'completed' }),
    request('PATCH', `/jobs/${concurrent.id}`, { status: 'completed' }),
  ]);
  assert.deepEqual(responses.map(v => v.statusCode).sort(), [200, 409]);
  assert.equal((await get(pool, 'items', stock.id))!.quantity, before - 1);
});
